const updateWorkResolved = `-- name: UpdateWorkResolved :exec
UPDATE item SET
  kind = ?1,
  year = ?2, released_on = ?3,
  followed_source = ?4, followed_source_id = ?5,
  identification_state = CASE WHEN identification_state = 'confirmed' THEN identification_state ELSE ?6 END
WHERE id = ?7 AND kind IN ('movie', 'episode', 'extra', 'other')
  -- Only when it changes something (D303, DL9).
  AND (kind, year, released_on, followed_source, followed_source_id, identification_state)
    IS NOT (?1, ?2, ?3, ?4,
      ?5,
      CASE WHEN identification_state = 'confirmed' THEN identification_state ELSE ?6 END)
`

type UpdateWorkResolvedParams struct {
	Kind                string
	Year                *int64
	ReleasedOn          *int64
	FollowedSource      *string
	FollowedSourceID    *string
	IdentificationState *string
	ID                  int64
}

// A title's item as the pass resolves it. A confirmed match is a person's: the pass never lowers it
// (D172). Its kind is how the pass files it: an extra whose film is gone is filed as a film (D162),
// and the title's kind and its sort keys' listing follow the item's by their keys (D426 section 2).
func (q *Queries) UpdateWorkResolved(ctx context.Context, arg UpdateWorkResolvedParams) error {
	_, err := q.db.ExecContext(ctx, updateWorkResolved,
		arg.Kind,
		arg.Year,
		arg.ReleasedOn,
		arg.FollowedSource,
		arg.FollowedSourceID,
		arg.IdentificationState,
		arg.ID,
	)
	return err
}

const updateWorkRuntime = `-- name: UpdateWorkRuntime :exec
UPDATE work SET runtime_ms = ?1
WHERE id = ?2 AND runtime_ms IS NOT ?1
`

type UpdateWorkRuntimeParams struct {
	RuntimeMs *int64
	ID        int64
}

// A title's running time as the pass resolves it; only when it changes (D303, DL9).
func (q *Queries) UpdateWorkRuntime(ctx context.Context, arg UpdateWorkRuntimeParams) error {
	_, err := q.db.ExecContext(ctx, updateWorkRuntime, arg.RuntimeMs, arg.ID)
	return err
}

const upsertOriginalText = `-- name: UpsertOriginalText :exec
INSERT INTO item_text (item_id, language, is_original, name, overview, tagline, search_alternates, sort_title)
VALUES (?1, ?2, 1, ?3, ?4, ?5,
  ?6, ?7)
ON CONFLICT (item_id, language) DO UPDATE SET
  is_original = 1, name = excluded.name, overview = excluded.overview, tagline = excluded.tagline,
  search_alternates = excluded.search_alternates, sort_title = excluded.sort_title
WHERE item_text.is_original IS NOT 1 OR item_text.name IS NOT excluded.name
  OR item_text.overview IS NOT excluded.overview OR item_text.tagline IS NOT excluded.tagline
  OR item_text.search_alternates IS NOT excluded.search_alternates OR item_text.sort_title IS NOT excluded.sort_title
`

type UpsertOriginalTextParams struct {
	ItemID           int64
	Language         string
	Name             string
	Overview         *string
	Tagline          *string
	SearchAlternates *string
	SortTitle        *string
}

// search_alternates is the name as the one normaliser folds it (D48), which both search indexes take.
// sort_title is the NFO's own sort name, which wins over the name's key (D402).
// A text already as derived is left alone (D303, DL9): nothing is written, and no index rewritten.
func (q *Queries) UpsertOriginalText(ctx context.Context, arg UpsertOriginalTextParams) error {
	_, err := q.db.ExecContext(ctx, upsertOriginalText,
		arg.ItemID,
		arg.Language,
		arg.Name,
		arg.Overview,
		arg.Tagline,
		arg.SearchAlternates,
		arg.SortTitle,
	)
	return err
}

